//! Endpoint-local receive storage. Packet slices retain their ordinary BytesMut
//! ownership; only empty tails are cached, and reclamation is delegated to bytes.
use std::collections::VecDeque;

use bytes::BytesMut;

pub(crate) struct ReceiveBuffers {
    spare: VecDeque<(BytesMut, usize)>,
    bytes: usize,
    max_bytes: usize,
    max_slots: usize,
    primed: bool,
}

impl ReceiveBuffers {
    pub(crate) fn new(max_bytes: usize, max_slots: usize) -> Self {
        Self {
            spare: VecDeque::new(),
            bytes: 0,
            max_bytes,
            max_slots,
            primed: false,
        }
    }

    pub(crate) fn take(&mut self, len: usize) -> (BytesMut, usize) {
        // Fill one receive geometry before rotating. Immediate reuse would
        // usually find the preceding packet still owned by its driver.
        self.primed |=
            self.spare.len() >= self.max_slots || len >= self.max_bytes.saturating_sub(self.bytes);
        if let Some((mut buffer, storage_bytes)) =
            self.primed.then(|| self.spare.pop_front()).flatten()
        {
            self.bytes -= storage_bytes;
            debug_assert!(buffer.is_empty());
            if buffer.try_reclaim(len) {
                return (buffer, storage_bytes);
            }
            // A connection can still own a packet slice. Dropping our empty
            // tail does not release or mutate that slice's backing storage.
        }
        let buffer = BytesMut::with_capacity(len);
        let storage_bytes = buffer.capacity();
        (buffer, storage_bytes)
    }

    pub(crate) fn recycle(&mut self, buffer: BytesMut, storage_bytes: usize) {
        debug_assert!(buffer.is_empty());
        if storage_bytes != 0
            && self.spare.len() < self.max_slots
            && storage_bytes <= self.max_bytes - self.bytes
        {
            self.bytes += storage_bytes;
            self.spare.push_back((buffer, storage_bytes));
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn retained_packet_is_not_overwritten() {
        let mut pool = ReceiveBuffers::new(64, 2);
        let (mut first, size) = pool.take(32);
        first.extend_from_slice(&[7; 32]);
        let packet = first.split_to(32);
        pool.recycle(first, size);
        let (mut second, size) = pool.take(32);
        second.extend_from_slice(&[9; 32]);
        assert_eq!(&packet[..], &[7; 32]);
        let _second_packet = second.split_to(32);
        pool.recycle(second, size);
        assert!(pool.bytes <= 64);
    }

    #[test]
    fn retired_slice_allows_reuse_and_cache_stays_bounded() {
        let mut pool = ReceiveBuffers::new(32, 1);
        let (mut data, size) = pool.take(32);
        data.extend_from_slice(&[3; 32]);
        let pointer = data.as_ptr();
        drop(data.split_to(32));
        pool.recycle(data, size);
        let (mut reused, size) = pool.take(32);
        assert_eq!(reused.as_ptr(), pointer);
        reused.extend_from_slice(&[4; 32]);
        assert_eq!(&reused[..], &[4; 32]);
        drop(reused.split_to(32));
        pool.recycle(reused, size);
        pool.recycle(BytesMut::with_capacity(32), 32);
        assert_eq!(pool.spare.len(), 1);
        assert_eq!(pool.bytes, 32);
    }
}
